import { useState } from "react";
import { useNavigate } from "react-router-dom";
export default function Login() {
  const navigate = useNavigate();  // <-- IMPORTANT
  const [form, setForm] = useState({ email: "", password: "" });
  const [message, setMessage] = useState("");
  const submitHandler = async (e) => {
    e.preventDefault();
setMessage("");
    try {
      const res = await fetch("/api/auth/login", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          email: form.email,
          password: form.password,
        }),
      });

      const data = await res.json();

      if (data.success) {
        localStorage.setItem("token", data.token);
        setMessage("Login Successful");
        alert("Login Successful");

        navigate("/mainHomePage");  
      } else {
        alert(data.message);
        setMessage(data.message);
      }
    } catch (err) {
      setMessage("Something went wrong");
    }
  };

  return (
    <>
    
    <div style={styles.container}>
      <div style={styles.card}>
        <h2 style={styles.title} >Login</h2>
    <form onSubmit={submitHandler} style={styles.form}>
      <input
        type="email"
        placeholder="Email"
        value={form.email}
        style={styles.input}
        onChange={(e) => setForm({ ...form, email: e.target.value })}
      />

      <input
        type="password"
        placeholder="Password"
        value={form.password}
           style={styles.input}
        onChange={(e) => setForm({ ...form, password: e.target.value })}
      />

      <button  style={styles.button} type="submit">Login</button>
      <p style={styles.ms}>{message}</p>
    </form>
    <p style={styles.text}>
          Dont have an account?  
          <a href="/signup" style={styles.link}>Signup</a>
    
        </p>
        </div>
        </div>
        </>

  );
}
const styles = {
  container: {
     display: "flex",
      justifyContent: "center",
       marginTop: "40px",
       height:"80vh",
       width:"100%" },
  card: {
     width: "350px",
      padding: "20px",
       border: "1px solid #ccc",
       width:"30%" ,
       borderRadius:"25px" },
  form: { 
    display: "flex",
     flexDirection: "column",
      gap: "10px",
      alignItems:"center",
       textAlign:"center"},
  input: {
     padding: "5px",
     borderRadius: "5px", 
     border: "1px solid #ccc",
     padding:"30px",
     marginTop:"40px",
     borderRadius:"10px",
     width:"85%",
     fontSize:"30px"},
  button: { padding: "10px", background: "blue", color: "white", border: "none"
    ,borderRadius:"10px",marginTop:"20%",cursor:"pointer",fontSize:"30px",fontweight:"bold",padding:"10px 40px"
   },
  link: { 
    color: "blue",
     marginLeft: "5px" },
  hading:{
    color:"red",
    fontSize:"50px",
    textAlign:"center"},
    text:{
        color:"white",
        fontSize:"25px",
        textAlign:"center"
    },
    ms:{
      color:"white"
    }

};
